'use strict';
// Explicit binary mutation of a genuine pinned workbook; not an independent XLSB producer.
const fs=require('node:fs/promises'),path=require('node:path'),crypto=require('node:crypto'),Zip=require('jszip');
function records(bytes){let p=0;const out=[];while(p<bytes.length){let id=bytes[p++];if(id&128)id=(id&127)|(bytes[p++]<<7);let n=0,s=0,a;do{a=bytes[p++];n+=(a&127)*2**s;s+=7;}while(a&128);out.push({id,b:Buffer.from(bytes.subarray(p,p+n))});p+=n;}return out;}
function encode(items){return Buffer.concat(items.map(({id,b})=>{const h=id<128?[id]:[(id&127)|128,id>>7];let n=b.length;do{h.push((n&127)|(n>=128?128:0));n=Math.floor(n/128);}while(n);return Buffer.concat([Buffer.from(h),b]);}));}
(async()=>{const root=__dirname,original=await fs.readFile(path.join(root,'../../xlsb-fixtures/pandas-test1.xlsb')),z=await Zip.loadAsync(original),items=records(await z.file('xl/styles.bin').async('nodebuffer'));const fill=items.find(x=>x.id===0x2d);fill.b.writeUInt32LE(1);fill.b[4]=5;fill.b.set([18,52,86,255],8);const border=items.find(x=>x.id===0x2e);border.b[1]=1;border.b[3]=5;border.b.set([255,0,0,255],7);let inside=false;for(const item of items){if(item.id===0x269)inside=true;else if(item.id===0x26a)inside=false;else if(inside&&item.id===0x2f){item.b[12]=1|64;item.b[13]=32;item.b[10]=100;item.b[11]=2;}}z.file('xl/styles.bin',encode(items));const bytes=await z.generateAsync({type:'nodebuffer'});await fs.writeFile(path.join(root,'derived-formatting.xlsb'),bytes);const derived=await Zip.loadAsync(bytes),hash=b=>crypto.createHash('sha256').update(b).digest('hex');for(const [name,file]of Object.entries((await Zip.loadAsync(original)).files))if(!file.dir&&name!=='xl/styles.bin'){if(hash(await file.async('nodebuffer'))!==hash(await derived.file(name).async('nodebuffer')))throw Error('Unexpected payload change '+name);}console.log('Only xl/styles.bin changed; all other part payloads exact. Derived SHA256 '+hash(bytes));})().catch(e=>{console.error(e);process.exitCode=1;});
